            if d.get(op[1]) != op[2]:
                return None
        elif k == "put":
            d[op[1]] = op[2]
        elif k == "del":
            d.pop(op[1], None)
        elif k == "cas":
            _, key, old, new, succ = op
            ok = d.get(key) == old
